<template>
    <div class="m4-view">
        <el-switch v-model="value1" active-text="按起止日期查询" inactive-text="按滑动时间查询">
        </el-switch><br><br>

        <div class="block">
            <!-- <span class="demonstration2">请选择起止日期&nbsp;&nbsp;</span> -->
            <el-date-picker v-model="pickdate11" type="daterange" align="right" unlink-panels range-separator="至"
                start-placeholder="开始日期" end-placeholder="结束日期" :picker-options="pickerOptions"
                :disabled="datePickerDisabled">
            </el-date-picker>

            <div class="block">
                <el-slider v-model="duration" :max="300" show-input :disabled="sliderDisabled">
                </el-slider>
            </div>
            <br>
        </div>
        <el-row :gutter="12">
            <div @click="handleClass">
                <el-col :span="6">
                    <el-card shadow="hover" class="el-card1">
                        <i class="el-icon-watermelon"></i>
                        &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;班级数据
                    </el-card>
                </el-col>
            </div>

            <div @click="handleTeacher">
                <el-col :span="6">
                    <el-card shadow="hover" class="el-card3">
                        <i class="el-icon-orange"></i>
                        &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;教师数据
                    </el-card>
                </el-col>
            </div>

            <div @click="handleGrade">
                <el-col :span="6">
                    <el-card shadow="hover" class="el-card2">
                        <i class="el-icon-cherry"></i>
                        &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;年级数据
                    </el-card>
                </el-col>
            </div>

            <div @click="handSubject">
                <el-col :span="6">
                    <el-card shadow="hover" class="el-card4">
                        <i class="el-icon-apple"></i>
                        &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;学科数据
                    </el-card>
                </el-col>
            </div>
        </el-row><br>

        <div ref="main" class="chart-container"></div>
        <br>


        <div ref="second" class="chart-container"></div>


        <br>
        <div class="third">
            <div id="chart1" class="chart"></div>
            <div id="chart2" class="chart"></div>
        </div>
    </div>
</template>

<style scoped>
.third {
    display: flex;
    justify-content: center;
    align-items: center;
    background: white;
}

.chart {
    width: 50%;
    height: 400px;

}

.chart-container {
    width: 100%;
    /* 设置初始宽度为 100% */
    height: 95%;
    /* 设置初始高度为 100% */
    background: white;
}


.block {
    width: 97%
}


.m4-view {
    height: 600px;
}

.el-icon-watermelon {
    transform: scale(3);
}

.el-icon-watermelon:hover {
    background: rgb(0, 149, 213);
    color: #ffffff;
}

.el-icon-cherry {
    transform: scale(3);
}

.el-icon-cherry:hover {
    background: rgb(101, 177, 1);
    color: #ffffff;
}

.el-icon-orange {
    transform: scale(3);
}

.el-icon-orange:hover {
    background: rgb(200, 51, 123);
    color: #ffffff;
}

.el-icon-apple {
    transform: scale(3);
}

.el-icon-apple:hover {
    background: rgb(238, 138, 56);
    color: #ffffff;
}

.el-card1:hover {
    color: rgb(0, 149, 213);
    /* 修改图标颜色 */
}

.el-card2:hover {
    color: rgb(101, 177, 1);
    /* 修改图标颜色 */
}

.el-card3:hover {
    color: rgb(200, 51, 123);
    /* 修改图标颜色 */
}

.el-card4:hover {
    color: rgb(238, 138, 56);
    /* 修改图标颜色 */
}
</style>

<script>
import * as echarts from 'echarts';
import * as axios from '@/handler/prehand'
import moment from 'moment'
export default {
    data() {
        return {
            value1: false,
            charttype: 0,
            duration: 7,
            checkDate: moment(new Date(Date.now())).format('YYYY-MM-DD'),
            startDate: '',
            pickdate11: '',
            endDate: '',
            limit: 6,
            barOption: {
                classData: ['className', 'praiseClasscount'],
                subjectData: ['subject', 'praiseSubjectcount'],
                gradeData: ['grade', 'praiseGradecount'],
                teacherData: ['teacherName', 'praiseTeachercount']
            },
            dimensions: [],
            source: [],
            myChart: null,

            thirdData:[],
            fifiData:[],

            gradefirstlayer: { '一年级': 0, '二年级': 0, '三年级': 0, '四年级': 0, '五年级': 0, '六年级': 0 },
            drilldata: [],
            secondChart: null,
            pickerOptions: {
                shortcuts: [{
                    text: '最近一周',
                    onClick(picker) {
                        const end = new Date();
                        const start = new Date();
                        start.setTime(start.getTime() - 3600 * 1000 * 24 * 7);
                        picker.$emit('pick', [start, end]);
                    }
                }, {
                    text: '最近一个月',
                    onClick(picker) {
                        const end = new Date();
                        const start = new Date();
                        start.setTime(start.getTime() - 3600 * 1000 * 24 * 30);
                        picker.$emit('pick', [start, end]);
                    }
                }, {
                    text: '最近三个月',
                    onClick(picker) {
                        const end = new Date();
                        const start = new Date();
                        start.setTime(start.getTime() - 3600 * 1000 * 24 * 90);
                        picker.$emit('pick', [start, end]);
                    }
                }]
            },
        }
    },

    methods: {
        //处理点击班级数据
        handleClass() {
            const url = '/tpi/charts'
            const charttype = 0;
            this.charttype = charttype;
            if (this.pickdate11) {
                this.startDate = moment(this.pickdate11[0]).format('YYYY-MM-DD');
                this.endDate = moment(this.pickdate11[1]).format('YYYY-MM-DD');
            }
            console.log(this.pickdate11[0])
            console.log(this.startDate);
            const data = {
                checkDate: this.checkDate,
                duration: this.duration,
                limit: this.limit,
                charttype: this.charttype,
                startDate: this.startDate,
                endDate: this.endDate
            };
            return axios.post(url, data).then(response => {
                const response2 = response.data.data;
                this.dimensions = this.barOption['classData'];

                if (response2 && response2.length > 0) {
                    for (const resp of response2) {
                        const singlesource = [];
                        singlesource.push(resp['className']);
                        singlesource.push(resp['praiseClasscount']);
                        this.source.push(singlesource)
                    }
                } else {
                    const singlesource = [];
                    singlesource.push("查询日期没有数据");
                    singlesource.push(0);
                    this.source.push(singlesource)
                    console.log('没有数据', this.dimensions, this.source);
                }
                // 在 mounted 钩子函数中初始化图表
                this.initChart();
                this.dimensions = [];
                this.source = [];
            }).catch(error => { this.$message.error('查询班级数据失败：' + error.message) }
            )
        },

        //处理点击年级数据
        handleGrade() {
            const url = '/tpi/charts'
            const charttype = 1;
            this.charttype = charttype;
            if (this.pickdate11) {
                this.startDate = moment(this.pickdate11[0]).format('YYYY-MM-DD');
                this.endDate = moment(this.pickdate11[1]).format('YYYY-MM-DD');
            }
            console.log(this.pickdate11[0])
            console.log(this.startDate);
            const data = {
                checkDate: this.checkDate,
                duration: this.duration,
                limit: this.limit,
                charttype: this.charttype,
                startDate: this.startDate,
                endDate: this.endDate
            };
            return axios.post(url, data).then(response => {
                const response2 = response.data.data;
                if (response2 && response2.length > 0) {

                    for (const resp of response2) {
                        let data3 = {};
                        this.gradefirstlayer[resp['grade']] = resp['praiseGradecount'];
                        data3['value'] = resp['praiseGradecount'];
                        data3['name'] = resp['grade']
                        this.thirdData.push(data3)
                    }
                }
                // 在 mounted 钩子函数中初始化图表
                this.secondInitChart();
                this.thirdChart();
                this.thirdData = [];
                this.gradefirstlayer = { '一年级': 0, '二年级': 0, '三年级': 0, '四年级': 0, '五年级': 0, '六年级': 0 };
            }).catch(error => { this.$message.error('查询年级数据失败：' + error.message) }
            )
        },


        //处理点击教师数据
        handleTeacher() {
            const url = '/tpi/charts'
            const charttype = 2;
            this.charttype = charttype;
            if (this.pickdate11) {
                this.startDate = moment(this.pickdate11[0]).format('YYYY-MM-DD');
                this.endDate = moment(this.pickdate11[1]).format('YYYY-MM-DD');
            }
            console.log(this.pickdate11[0])
            console.log(this.startDate);
            const data = {
                checkDate: this.checkDate,
                duration: this.duration,
                limit: this.limit,
                charttype: this.charttype,
                startDate: this.startDate,
                endDate: this.endDate
            };
            return axios.post(url, data).then(response => {
                const response2 = response.data.data;
                this.dimensions = this.barOption['teacherData'];

                if (response2 && response2.length > 0) {
                    for (const resp of response2) {
                        const singlesource = [];
                        singlesource.push(resp['teacherName']);
                        singlesource.push(resp['praiseTeachercount']);
                        this.source.push(singlesource)
                    }
                } else {
                    const singlesource = [];
                    singlesource.push("查询日期没有数据");
                    singlesource.push(0);
                    this.source.push(singlesource)
                    console.log('没有数据', this.dimensions, this.source);
                }
                // 在 mounted 钩子函数中初始化图表
                this.initChart();
                this.dimensions = [];
                this.source = [];
            }).catch(error => { this.$message.error('查询教师数据失败：' + error.message) }
            )
        },

        handSubject(){
            const url = '/tpi/charts'
            const charttype = 3;
            this.charttype = charttype;
            if (this.pickdate11) {
                this.startDate = moment(this.pickdate11[0]).format('YYYY-MM-DD');
                this.endDate = moment(this.pickdate11[1]).format('YYYY-MM-DD');
            }
            const data = {
                checkDate: this.checkDate,
                duration: this.duration,
                limit: this.limit,
                charttype: this.charttype,
                startDate: this.startDate,
                endDate: this.endDate
            };
            return axios.post(url, data).then(response => {
                const response2 = response.data.data;
                if (response2 && response2.length > 0) {
                    for (const resp of response2) {
                        let data3 = {};
                        data3['value'] = resp['praiseSubjectcount'];
                        data3['name'] = resp['subject']
                        this.fifiData.push(data3)
                    }
                }
                // 在 mounted 钩子函数中初始化图表
                this.fourthChart();
                console.log("第yi次",this.fifiData)
                this.fifiData = [];
                console.log("第二次",this.fifiData)
            }).catch(error => { this.$message.error('查询年级数据失败：' + error.message) }
            )
        },


        test() {
            const url = '/tpi/charts'
            const data = {
                checkDate: '2024-04-03',
                duration: 100,
                limit: 6,
                charttype: 3
            };
            axios.post(url, data).then(response => {
                console.log(response.data.data)
            })

        },
        //加载第一个图表
        initChart() {
            // 获取容器 DOM 元素
            var chartDom = this.$refs.main;
            // 初始化图表，传入容器的宽度和高度
            this.myChart = echarts.init(chartDom);
            // 图表配置项
            var option = {
                dataset: [
                    {
                        dimensions: this.dimensions,
                        source: this.source
                    },
                    {
                        transform: {
                            type: 'sort',
                            config: { dimension: this.dimensions[1], order: 'desc' }
                        }
                    }
                ],
                xAxis: {
                    type: 'category',
                    axisLabel: { interval: 0, rotate: 0 }
                },
                yAxis: {},
                series: {
                    type: 'bar',
                    encode: { x: this.dimensions[0], y: this.dimensions[1] },
                    datasetIndex: 0
                },
                // 添加 tooltip 配置项
                tooltip: {
                    trigger: 'axis',
                    axisPointer: {
                        type: 'shadow'
                    }
                }
            };
            // 设置图表配置项
            this.myChart.setOption(option);
        },

        secondInitChart() {
            var chartDom = this.$refs.second;
            // 初始化图表，传入容器的宽度和高度
            this.secondChart = echarts.init(chartDom);
            var option = {
                xAxis: {
                    data: ['一年级', '二年级', '三年级', '四年级', '五年级', '六年级']
                },
                yAxis: {},
                dataGroupId: '',
                animationDurationUpdate: 500,
                series: {
                    type: 'bar',
                    id: 'sales',
                    data: [
                        {
                            value: this.gradefirstlayer['一年级'],
                            groupId: '一年级'
                        },
                        {
                            value: this.gradefirstlayer['二年级'],
                            groupId: '二年级'
                        },
                        {
                            value: this.gradefirstlayer['三年级'],
                            groupId: '三年级'
                        },
                        {
                            value: this.gradefirstlayer['四年级'],
                            groupId: '四年级'
                        },
                        {
                            value: this.gradefirstlayer['五年级'],
                            groupId: '五年级'
                        },
                        {
                            value: this.gradefirstlayer['六年级'],
                            groupId: '六年级'
                        },
                    ],
                    universalTransition: {
                        enabled: true,
                        divideShape: 'clone'
                    }
                },
                tooltip: {
                    trigger: 'axis',
                    axisPointer: {
                        type: 'shadow'
                    }
                }
            };

            this.secondChart.on('click', (event) => {
                console.log(event.data);
                if (event.data != null && isNaN(event.data)) {
                    const url = '/tpi/charts'
                    if (this.pickdate11) {
                        this.startDate = moment(this.pickdate11[0]).format('YYYY-MM-DD');
                        this.endDate = moment(this.pickdate11[1]).format('YYYY-MM-DD');
                    }
                    const data = {
                        checkDate: this.checkDate,
                        duration: this.duration,
                        limit: this.limit,
                        charttype: 5,
                        startDate: this.startDate,
                        endDate: this.endDate,
                        grade: event.data.groupId
                    };
                    axios.post(url, data).then(response => {
                        const response3 = response.data.data;
                        this.drilldata = [];
                        if (response3 && response3.length > 0) {
                            for (const resp of response3) {
                                const singledrill = [];
                                singledrill.push(resp['className']);
                                singledrill.push(resp['praiseClasscount']);
                                this.drilldata.push(singledrill)
                            }
                        } else {
                            const singledrill = [];
                            singledrill.push('查询日期没有数据');
                            singledrill.push(0);
                            this.drilldata.push(singledrill)
                        }

                        const drilldownData = {
                            dataGroupId: event.data.groupId,
                            data: this.drilldata
                        }

                        const x = [];
                        const y = [];
                        for (const item of drilldownData.data) {

                            x.push(item[0])
                            y.push(item[1])
                        }
                        this.secondChart.setOption({
                            xAxis: { data: x },
                            series: {
                                type: 'bar',
                                id: 'sales',
                                dataGroupId: event.data.groupId,
                                data: y,
                                universalTransition: {
                                    enabled: true,
                                    divideShape: 'clone'
                                }
                            },
                            tooltip: {
                                trigger: 'axis',
                                axisPointer: {
                                    type: 'shadow'
                                }
                            },
                            graphic: [
                                {
                                    type: 'text',
                                    left: 50,
                                    top: 20,
                                    style: {
                                        text: 'back',
                                        fontSize: 18
                                    },
                                    onclick: () => {
                                        this.secondChart.setOption(option);
                                    }
                                }
                            ]
                        })

                    }).catch(error => {
                        return this.$message.error("未取到数据：" + error.message)
                    })
                }
                else { return; }
            })

            this.secondChart.setOption(option);

        },

        fourthChart() {
            var chartDom2 = document.getElementById('chart2');
            var myChart2 = echarts.init(chartDom2);
            var option2 = {
                tooltip: {
                    trigger: 'item',
                    formatter: '{a} <br/>{b} : {c} ({d}%)'
                },
                series: [
                    {
                        name: 'Radius Mode',
                        type: 'pie',
                        radius: [20, 140],
                        center: ['50%', '50%'],
                        roseType: 'radius',
                        itemStyle: {
                            borderRadius: 5
                        },
                        label: {
                            show: true
                        },
                        emphasis: {
                            label: {
                                show: true
                            }
                        },
                        data: this.fifiData
                    }
                ]
            };
            myChart2.setOption(option2);
        },
        thirdChart() {
            var chartDom1 = document.getElementById('chart1');
            var myChart1 = echarts.init(chartDom1);
            var option1 = {
                tooltip: {
                    trigger: 'item',
                    formatter: '{a} <br/>{b} : {c} ({d}%)'
                },
                series: [
                    {
                        name: 'Radius Mode',
                        type: 'pie',
                        radius: [20, 140],
                        center: ['50%', '50%'],
                        roseType: 'radius',
                        itemStyle: {
                            borderRadius: 5
                        },
                        label: {
                            show: true
                        },
                        emphasis: {
                            label: {
                                show: true
                            }
                        },
                        data: this.thirdData
                    }
                ]
            };
            myChart1.setOption(option1);
        },

        resizeChart() {
            // 动态调整图表大小，重新获取容器的宽度和高度，并设置给图表
            var chartDom = this.$refs.main;
            var width = chartDom.clientWidth;
            var height = chartDom.clientHeight;
            this.myChart.resize({ width: width, height: height });

            var chartDom2 = this.$refs.second;
            var width2 = chartDom2.clientWidth;
            var height2 = chartDom2.clientHeight;
            this.secondChart.resize({ width: width2, height: height2 });
        }

    },


    mounted() {

        this.handSubject().then(response => {
            console.log("取到数据，初始化图表", response)
        }).catch(error => {
            return this.$message.error("未取到数据：" + error.message)
        })



        this.handleClass().then(response => {
            console.log("取到数据，初始化图表", response)
        }).catch(error => {
            return this.$message.error("未取到数据：" + error.message)
        })

        this.handleGrade().then(response => { console.log("取到数据，初始化图表", response) }).catch(error => {
            return this.$message.error("未取到数据：" + error.message)
        })


        // 监听窗口大小变化事件，动态调整图表大小
        window.addEventListener('resize', this.resizeChart);
    },

    computed: {
        // 根据开关状态来确定日期选择器的禁用状态
        datePickerDisabled() {
            return !this.value1;
        },
        // 根据开关状态来确定滑动条的禁用状态
        sliderDisabled() {
            return this.value1;
        }
    },

    beforeDestroy() {
        // 在组件销毁前移除窗口大小变化事件监听
        window.removeEventListener('resize', this.resizeChart);

        if (this.myChart) {
            this.myChart.dispose();
        }
        if (this.secondChart) {
            this.secondChart.dispose();
        }
    }
}

</script>
